package org.openclaw.questmarkerserviceprobe;
import android.app.Service;
import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.content.Intent;
import android.os.*;
import android.Manifest;
import android.content.pm.PackageManager;
import android.hardware.camera2.*;
import android.media.*;
import android.graphics.*;
import android.util.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.util.*;

/** Ordinary Android 2D Camera2 detector capability probe; no immersive/XR claims. */
public class MainActivity extends Service {
 private static final String TAG="QuestMarkerOptical";
 private static native byte[] rgbaFromYuv(ByteBuffer y,ByteBuffer u,ByteBuffer v,int w,int h,int yr,int yp,int ur,int up,int vr,int vp,int ds);
 private static native float[] trackBoth(byte[] rgba,int w,int h,double[] k,double[] xy,int[] words,double boardM);
 private HandlerThread worker; private Handler handler; private CameraDevice camera; private CameraCaptureSession session; private ImageReader reader;
 private ImageView imageView; private TextView label; private ServerSocket server; private BufferedWriter records;
 private volatile byte[] jpeg=new byte[0],rawJpeg=new byte[0],rawPixels=new byte[0]; private volatile String state="starting",cameraInfo="",status="{}";
 private static final class Snapshot{final byte[] image,raw;final String metadata;Snapshot(byte[] image,byte[] raw,String metadata){this.image=image;this.raw=raw;this.metadata=metadata;}}
 private volatile Snapshot snapshot;
 private volatile boolean alive=true; private long startMs,lastProcessed; private int frames,arucoHits,dotHits; private double[] xy=new double[56],k=new double[4];private int[] words=new int[56];
 private volatile double boardM=.12; private float[] intrinsic; private Rect active,crop; private String cameraId=""; private int dataSpace;
 public void onCreate(){super.onCreate();Log.i(TAG,"onCreate foreground optical diagnostic service; no VR/Guardian operation");
  NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("optical-probe","Quest camera optical diagnostic",NotificationManager.IMPORTANCE_LOW));
  Notification n=new Notification.Builder(this,"optical-probe").setContentTitle("Optical camera diagnostic running").setContentText("Captures Quest camera for marker test. No XR or boundary changes.").setSmallIcon(android.R.drawable.ic_menu_camera).build();startForeground(7,n);
  worker=new HandlerThread("marker-camera");worker.start();handler=new Handler(worker.getLooper());startMs=SystemClock.elapsedRealtime();
  try{System.loadLibrary("probe_jni");initContract();records=new BufferedWriter(new FileWriter(new File(getExternalFilesDir(null),"probe-sensor.jsonl"),true));startServer();}catch(Throwable e){fail(e);stopSelf();return;}
  if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){fail(new SecurityException("Camera permission not granted"));stopSelf();return;}
  handler.post(()->openCamera());handler.postDelayed(()->stopSelf(),85000);
 }
 public android.os.IBinder onBind(Intent intent){return null;}
 public int onStartCommand(Intent intent,int flags,int id){return START_NOT_STICKY;}
 private void initContract()throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getAssets().open("marker-contract.json")){byte[] b=new byte[4096];int n;while((n=in.read(b))>0)bytes.write(b,0,n);}JSONObject contract=new JSONObject(bytes.toString("UTF-8"));JSONArray corners=contract.getJSONArray("cornerFrames"),markers=contract.getJSONArray("markers");double space=contract.getDouble("dotSpacingM");for(int c=0;c<4;c++){JSONObject corner=corners.getJSONObject(c);JSONArray center=corner.getJSONArray("center"),u=corner.getJSONArray("u"),v=corner.getJSONArray("v");for(int d=0;d<7;d++){int t=d==0?0:((d-1)%3)+1;JSONArray arm=d<4?u:v;int p=c*7+d;xy[p*2]=center.getDouble(0)-.06+t*space*arm.getDouble(0);xy[p*2+1]=center.getDouble(1)-.06+t*space*arm.getDouble(1);for(int m=0;m<2;m++)words[m*28+p]=markers.getJSONObject(m).getJSONArray("cornerCodes").getJSONArray(c).getInt(d);}}}
 private Integer vendorInt(Object o){if(o instanceof Number)return ((Number)o).intValue();if(o instanceof byte[]&&((byte[])o).length>0)return (int)((byte[])o)[0];return null;}
 @SuppressWarnings({"MissingPermission","unchecked"}) private void openCamera(){try{CameraManager mgr=(CameraManager)getSystemService(CAMERA_SERVICE);String chosen=null;StringBuilder info=new StringBuilder();for(String id:mgr.getCameraIdList()){CameraCharacteristics c=mgr.getCameraCharacteristics(id);Integer source=null,position=null;for(CameraCharacteristics.Key<?> key:c.getKeys()){if(key.getName().equals("com.meta.extra_metadata.camera_source"))source=vendorInt(c.get((CameraCharacteristics.Key)key));if(key.getName().equals("com.meta.extra_metadata.position"))position=vendorInt(c.get((CameraCharacteristics.Key)key));}info.append(id+":source="+source+",position="+position+" ");if(source!=null&&source==0&&(chosen==null||(position!=null&&position==0)))chosen=id;}
  cameraInfo=info.toString();Log.i(TAG,"cameras "+cameraInfo);if(chosen==null)throw new Exception("No passthrough source=0 camera");cameraId=chosen;CameraCharacteristics c=mgr.getCameraCharacteristics(chosen);intrinsic=c.get(CameraCharacteristics.LENS_INTRINSIC_CALIBRATION);active=c.get(CameraCharacteristics.SENSOR_INFO_ACTIVE_ARRAY_SIZE);crop=active;android.util.Size[] sizes=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP).getOutputSizes(ImageFormat.YUV_420_888);android.util.Size selected=sizes[0];for(android.util.Size size:sizes)if(size.getWidth()==1280&&size.getHeight()==1280)selected=size;
  reader=ImageReader.newInstance(selected.getWidth(),selected.getHeight(),ImageFormat.YUV_420_888,3);reader.setOnImageAvailableListener(r->{Image im=r.acquireLatestImage();if(im==null)return;try{long now=SystemClock.elapsedRealtime();if(now-lastProcessed>=100){lastProcessed=now;process(im);}}catch(Throwable e){fail(e);}finally{im.close();}},handler);
  mgr.openCamera(chosen,new CameraDevice.StateCallback(){public void onOpened(CameraDevice d){camera=d;state="camera "+cameraId+" open "+reader.getWidth()+"x"+reader.getHeight();Log.i(TAG,state);try{CaptureRequest.Builder b=d.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);b.addTarget(reader.getSurface());d.createCaptureSession(Arrays.asList(reader.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){session=s;try{s.setRepeatingRequest(b.build(),new CameraCaptureSession.CaptureCallback(){public void onCaptureCompleted(CameraCaptureSession ss,CaptureRequest request,TotalCaptureResult result){float[] measured=result.get(CaptureResult.LENS_INTRINSIC_CALIBRATION);if(measured!=null)intrinsic=measured;Rect rect=result.get(CaptureResult.SCALER_CROP_REGION);if(rect!=null)crop=rect;}},handler);}catch(Exception e){fail(e);}}public void onConfigureFailed(CameraCaptureSession s){fail(new Exception("Capture configuration failed"));}},handler);}catch(Exception e){fail(e);}}public void onDisconnected(CameraDevice d){state="disconnected";d.close();Log.e(TAG,state);}public void onError(CameraDevice d,int error){state="camera error "+error;d.close();Log.e(TAG,state);}},handler);
 }catch(Throwable e){fail(e);}}
 private void process(Image im)throws Exception{long tick=SystemClock.elapsedRealtime();int w=im.getWidth(),h=im.getHeight();Image.Plane[] p=im.getPlanes();dataSpace=Build.VERSION.SDK_INT>=33?im.getDataSpace():0;
  byte[] rgba=rgbaFromYuv(p[0].getBuffer(),p[1].getBuffer(),p[2].getBuffer(),w,h,p[0].getRowStride(),p[0].getPixelStride(),p[1].getRowStride(),p[1].getPixelStride(),p[2].getRowStride(),p[2].getPixelStride(),dataSpace);
  if(intrinsic==null||crop==null)throw new Exception("Measured camera calibration unavailable");double ar=(double)w/h,cw=crop.width(),ch=crop.height();if(cw/ch>ar)cw=ch*ar;else ch=cw/ar;double left=crop.centerX()-cw/2.,top=crop.centerY()-ch/2.;k[0]=intrinsic[0]*w/cw;k[1]=intrinsic[1]*h/ch;k[2]=(intrinsic[2]-left)*w/cw;k[3]=(intrinsic[3]-top)*h/ch;
  rawPixels=rgba;double activeBoard=boardM;float[] result=trackBoth(rgba,w,h,k,xy,words,activeBoard);frames++;if(result[0]==1)arucoHits++;if(result[1]==1)dotHits++;int[] pixels=new int[w*h];for(int i=0;i<pixels.length;i++){int q=i*4;pixels[i]=0xff000000|((rgba[q]&255)<<16)|((rgba[q+1]&255)<<8)|(rgba[q+2]&255);}Bitmap bm=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);bm.setPixels(pixels,0,w,0,0,w,h);ByteArrayOutputStream raw=new ByteArrayOutputStream();bm.compress(Bitmap.CompressFormat.JPEG,88,raw);rawJpeg=raw.toByteArray();
  Canvas canvas=new Canvas(bm);Paint paint=new Paint(3);paint.setStrokeWidth(4);paint.setStyle(Paint.Style.STROKE);for(int mode=0;mode<2;mode++)if(result[mode]==1){paint.setColor(mode==0?Color.CYAN:Color.MAGENTA);int b=2+34*mode;Path path=new Path();path.moveTo(result[b+18],result[b+19]);for(int j=1;j<4;j++)path.lineTo(result[b+18+j*2],result[b+19+j*2]);path.close();canvas.drawPath(path,paint);}
  paint.setStyle(Paint.Style.FILL);paint.setColor(Color.BLACK);canvas.drawRect(0,0,w,100,paint);paint.setColor(Color.WHITE);paint.setTextSize(25);canvas.drawText("QUEST CAMERA2 OPTICAL PROBE — NOT UNITY / XR ACCEPTANCE",16,30,paint);canvas.drawText("ArUco: "+(result[0]==1?"ID "+(int)result[2]:"SEARCHING")+" | Dots: "+(result[1]==1?"ID "+(int)result[36]:"SEARCHING")+" | frame "+frames,16,64,paint);paint.setTextSize(18);canvas.drawText("Actual sensor image; new detections only; no injected feed, stale hold or world anchor",16,90,paint);
  ByteArrayOutputStream out=new ByteArrayOutputStream();bm.compress(Bitmap.CompressFormat.JPEG,88,out);jpeg=out.toByteArray();long now=SystemClock.elapsedRealtime();JSONObject obj=new JSONObject();obj.put("state",state);obj.put("cameras",cameraInfo);obj.put("cameraId",cameraId);obj.put("frames",frames);obj.put("arucoHits",arucoHits);obj.put("dotHits",dotHits);obj.put("arucoRc",result[0]);obj.put("dotRc",result[1]);obj.put("sensorTimestampNs",im.getTimestamp());obj.put("elapsedMs",now-startMs);obj.put("processMs",now-tick);obj.put("boardWidthM",activeBoard);obj.put("width",w);obj.put("height",h);obj.put("dataSpace",dataSpace);obj.put("yuvRange",((dataSpace>>27)&7)==2?"limited":"full-or-unknown");obj.put("intrinsics",new JSONArray(k));obj.put("nativeResult",new JSONArray(result));status=obj.toString();snapshot=new Snapshot(jpeg,rgba,status);records.write(status);records.newLine();records.flush();if(frames%20==0)Log.i(TAG,status);
 }
 private void startServer()throws Exception{server=new ServerSocket(8879,4,InetAddress.getByName("127.0.0.1"));new Thread(()->{while(alive){try{Socket s=server.accept();new Thread(()->serve(s)).start();}catch(Exception e){if(alive)Log.e(TAG,"server",e);}}},"probe-http").start();}
 private void serve(Socket s){try{s.setSoTimeout(2000);String req=new BufferedReader(new InputStreamReader(s.getInputStream())).readLine();String path=req==null?"":req.split(" ")[1];byte[] body;String type;if(path.startsWith("/config?width=")){double requested=Double.parseDouble(path.substring(path.indexOf("=")+1));if(requested<.06||requested>.5)throw new Exception("bad nominal metric extent");boardM=requested;body=("{\"boardWidthM\":"+boardM+"}").getBytes("UTF-8");type="application/json";}else if(path.startsWith("/snapshot")){Snapshot capture=snapshot;if(capture==null){body=status.getBytes("UTF-8");}else{JSONObject packet=new JSONObject();packet.put("metadata",new JSONObject(capture.metadata));packet.put("jpegBase64",android.util.Base64.encodeToString(capture.image,android.util.Base64.NO_WRAP));if(path.contains("raw=1"))packet.put("rgbaBase64",android.util.Base64.encodeToString(capture.raw,android.util.Base64.NO_WRAP));body=packet.toString().getBytes("UTF-8");}type="application/json";}else if(path.startsWith("/raw.rgba")){body=rawPixels;type="application/octet-stream";}else if(path.startsWith("/raw.jpg")){body=rawJpeg;type="image/jpeg";}else if(path.startsWith("/frame.jpg")){body=jpeg;type="image/jpeg";}else{body=status.getBytes("UTF-8");type="application/json";}OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: "+type+"\r\nContent-Length: "+body.length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(body);out.flush();s.close();}catch(Exception e){try{s.close();}catch(Exception ignored){}}}
 private void fail(Throwable e){state="ERROR "+e;Log.e(TAG,state,e);try{status=new JSONObject().put("state",state).put("frames",frames).toString();}catch(Exception ignored){}}
 public void onDestroy(){alive=false;try{if(server!=null)server.close();if(records!=null)records.close();}catch(Exception ignored){}if(session!=null)session.close();if(camera!=null)camera.close();if(reader!=null)reader.close();if(worker!=null)worker.quitSafely();super.onDestroy();}
}
